@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.LastLowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.LastLowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.LastLowStockCount
                </p>
                <p class="card-text text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="text-success">● Active</span>
                        <br /><small class="text-muted">Refreshing every 10s</small>
                    }
                    else
                    {
                        <span class="text-secondary">● Stopped</span>
                    }
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text">@WarehouseState.CurrentWarehouseId</p>
                <small class="text-muted">@WarehouseState.CurrentWarehouseName</small>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h4>Activity Log</h4>
    <ul class="list-group">
        @foreach (var entry in _log.TakeLast(10).Reverse())
        {
            <li class="list-group-item list-group-item-sm">@entry</li>
        }
    </ul>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private readonly List<string> _log = new();

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately
        StopPolling();
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.CurrentWarehouseName}");
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _isPolling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Initial fetch immediately
        await FetchAndPublishAsync();

        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await FetchAndPublishAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task FetchAndPublishAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Polled {WarehouseState.CurrentWarehouseId}: {count} low-stock items");

        // Publish to ALL subscribers (sidebar badge, this page, any other component)
        AlertService.PublishNewCount(count);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

